import{c as A,Q as a,j as l,m as e}from"./chunks/framework.DOi4mjdC.js";const o="/assets/zh-cn_image_0000002404199037.DkXzT0iZ.png",r="/assets/zh-cn_image_0000002411076626.BzpUHMob.png",s="/assets/%E4%B8%8D%E4%BD%BF%E8%83%BDIBShare%E6%A8%A1%E6%9D%BF%E7%9A%84Matmul%E6%B5%81%E6%B0%B4%E7%A4%BA%E6%84%8F%E5%9B%BE.vpglg6gC.png",u="data:image/png;base64,",p="/assets/zh-cn_image_0000002404200417.UXZVcg5q.png",n="/assets/zh-cn_image_0000002444817149.DT6DsDiK.png",b=JSON.parse('{"title":"Matmul高阶API使能IBShare模板共享B矩阵数据","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul高阶API使能IBShare模板共享B矩阵数据","slug":"matmul高阶api使能ibshare模板共享b矩阵数据"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能IBShare模板共享B矩阵数据.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能IBShare模板共享B矩阵数据.md"}'),i={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能IBShare模板共享B矩阵数据.md"};function g(q,t,c,d,B,h){return a(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="matmul高阶api使能ibshare模板共享b矩阵数据" tabindex="-1">Matmul高阶API使能IBShare模板共享B矩阵数据 <a class="header-anchor" href="#matmul高阶api使能ibshare模板共享b矩阵数据" aria-label="Permalink to &quot;Matmul高阶API使能IBShare模板共享B矩阵数据&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例呈现了在矩阵乘算子场景中，使用Matmul高阶API进行矩阵乘法计算，B矩阵使能IBShare对算子性能的提升效果。IBShare功能通过共享L1 Buffer上相同的A矩阵或B矩阵数据，减少重复的MTE2数据搬运开销，提升算子性能。该功能支持A矩阵和B矩阵其中一个矩阵使能IBShare，也支持A矩阵和B矩阵同时使能IBShare。</p><ul><li><p>使能IBShare的适用场景</p><p>MIX场景（包含矩阵计算和矢量计算）下，多个AIV的A矩阵或B矩阵GM地址相同，且多个AIV复用的A矩阵或B矩阵在L1 Buffer上全载。</p></li><li><p>使能IBShare的约束条件</p><ul><li>A矩阵和B矩阵同时使能IBShare的场景，同一算子中其它Matmul对象的A矩阵和B矩阵也必须同时使能IBShare。</li><li>A矩阵和B矩阵同时使能IBShare的场景，获取矩阵计算结果时，只支持调用IterateAll接口，且只支持输出到Global Memory。</li></ul></li></ul><p>本案例的算子规格如下：</p><p><strong>表 1</strong> 算子规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;输入&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;a&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;64, 384&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;b&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;384, 256&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>当前案例使用的AI处理器共20个核，每个核中包含1个AIC核和2个AIV核。因为输入shape较小，本案例以单核为示例，参考SetDim接口在MIX模式下的使用，在Tiling程序中设置参与运算的核数为2。Tiling参数如下：</p><ul><li>原始shape：M=64, N= 256, K=384。</li><li>单核shape：singleCoreM=32，singleCoreN=256，singleCoreK=384。A矩阵拆成两半，一半在AIV0上处理，一半在AIV1上处理；AIV0和AIV1使用的B矩阵数据相同。</li><li>基本块shape：baseM=32，baseN=256，baseK=64。</li><li>L1缓存相关Tiling参数：stepM=1，stepN=1，stepKa=6，stepKb=6。</li></ul><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>使用msProf工具获取<a href="./../../性能分析/获取性能数据.html#section17259539153513">算子仿真流水图</a>和<a href="./../../性能分析/获取性能数据.html#section17953123893415">上板Profiling</a>数据，因为IBShare功能主要是通过共享L1 Buffer上相同的A矩阵或B矩阵数据，减少重复的MTE2数据搬运开销，所以重点分析MTE2的流水情况。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><ul><li><p>优化前的流水图如下，不使能IBShare模板，默认使用的Norm模板。黑框标识AIV0发起的MTE2搬运流水：MTE2总共搬运了12次，其中A矩阵搬运了6次（stepM*stepKa=6），B矩阵搬运了6次（stepN*stepKb=6）。红框标识的AIV1发起的MTE2搬运流水，跟AIV0基本一致。在该案例中，因为AIV1使用的B矩阵跟AIV0使用的B矩阵数据相同，且singleCoreN=baseN*stepN，singleCoreK=baseK*stepKb，即B矩阵可以在L1全载。考虑在AIV0搬入B矩阵到L1 Buffer后，将B矩阵数据缓存在L1 Buffer上等待AIV1进行复用，进而节省B矩阵的MTE2重复搬运开销。</p><p><img src="'+o+'" alt=""></p></li><li><p>优化前的Profiling数据如下，C列的aic_time是10.29us，K列的aic_mte2_time是5.56us。</p><p><img src="'+r+'" alt=""></p></li></ul><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><p>下图是不使能IBShare模板（默认使用Norm模板）的Matmul计算流水示意图。MTE2分多次从Global Memory搬运基本块到A1或B1，即使前后两次搬运的B矩阵基本块数据是相同的数据，也会重复搬运。</p><p><strong>图 1</strong> 不使能IBShare模板的Matmul流水示意图<br><img src="'+s+'" alt="" title="不使能IBShare模板的Matmul流水示意图"></p><p>下图是使能IBShare模板的Matmul计算流水示意图。MTE2分多次从Global Memory搬运基本块到A1或B1，若前后两次搬运的B矩阵基本块数据相同，不会重复搬运，第一次搬运到B1内的数据会被复用。</p><p><strong>图 2</strong> 使能IBShare模板的Matmul流水示意图<br><img src="'+u+`" alt="" title="使能IBShare模板的Matmul流水示意图"></p><p>Matmul API使能IBShare模板共享B矩阵的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_ibshareB" target="_blank" rel="noreferrer">仅B矩阵使能IBShare样例</a>。使能IBShare功能的主要步骤如下：</p><ol><li><p>创建Matmul对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ASCENDC_CUBE_ONLY</span></span>
<span class="line"><span>#include &quot;lib/matmul_intf.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using A_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, AType&gt;;</span></span>
<span class="line"><span>using B_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BType, false, LayoutMode::NONE, true&gt;; // 设置B矩阵的IBSHARE参数为true</span></span>
<span class="line"><span>using C_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, CType&gt;;</span></span>
<span class="line"><span>using BIAS_TYPE =  AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BiasType&gt;;</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_IBSHARE_NORM&gt; matmulObj; // 使用默认的IBShare模板参数CFG_IBSHARE_NORM定义Matmul对象</span></span></code></pre></div></li></ol><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><ul><li><p>优化后的流水图如下，黑框标识的AIV0发起的MTE2搬运流水，与优化前一致。红框标识的AIV1发起的MTE2搬运流水，相较于优化前的A矩阵和B矩阵一共12次MTE2数据搬运，减少到了仅6次A矩阵的MTE2数据搬运，省去了B矩阵的6次MTE2数据搬运开销。</p><p><img src="`+p+'" alt=""></p></li><li><p>优化后的Profiling数据如下，C列的aic_time是9.93us，较优化前的10.29us提升了3.55%。K列的aic_mte2_time是4.71us，较优化前的5.56us提升了15.46%。</p><p><img src="'+n+'" alt=""></p></li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>MIX场景（包含矩阵计算和矢量计算）下，若多个AIV的A矩阵或B矩阵GM地址相同，且多个AIV复用的A矩阵/B矩阵在L1 Buffer上全载。可以考虑使能IBShare模板，通过共享L1 Buffer上相同的A矩阵或B矩阵数据，减少重复的MTE2数据搬运开销，提升算子性能。</p>',24)])])}const I=A(i,[["render",g]]);export{b as __pageData,I as default};
